_talkToNPC(npc) {
    // Check for special dialogs (Master Wu watering can)
    let dialog = null;

    if (npc.id === 'sage' && npc.specialDialogs) {
        if (this.tutorial.firstPlant && !this.player.hasTool('wateringCan')) {
            // After first plant, Master Wu gives the watering can
            dialog = npc.specialDialogs.give_watering_can;
        } else if (this.player.hasTool('wateringCan')) {
