    // Fall back to normal dialog rotation
    if (!dialog) {
        dialog = npc.dialog[npc.dialogIndex];
        npc.dialogIndex = (npc.dialogIndex + 1) % npc.dialog.length;
    }

    if (dialog) {
        this.dialog.show(dialog);
        this.gameState = 'dialog';
    }
}

