/**
 * AssetLoader — Sprite loading from PNG files with procedural fallback.
 * API-compatible with AssetGenerator (same getSprite() interface).
 * 
 * Priority:
 *   1. Loaded PNG from assets/sprites/{name}.png
 *   2. AssetGenerator procedural fallback
 * 
 * Place PNG files in assets/sprites/ (e.g. assets/sprites/player.png)
 * They are loaded once and cached.
 */

export class AssetLoader {
    constructor(assetGenerator) {
        this.fallback = assetGenerator;
        this.pngCache = new Map();
        this.loading = new Map();   // Track in-flight loads
        this._loaded = false;
    }

    /**
     * Get a sprite by name — tries PNG first, falls back to procedural
     * @param {string} name - Sprite identifier
     * @returns {HTMLCanvasElement|HTMLImageElement} Sprite
     */
    getSprite(name, ...params) {
        const key = name + (params.length ? '_' + params.join('_') : '');

        // Check PNG cache
        if (this.pngCache.has(key)) {
            const cached = this.pngCache.get(key);
            if (cached) return cached;
        }

        // Check if we have a PNG for the base name (without params)
        const baseKey = name;
        if (this.pngCache.has(baseKey)) {
            const cached = this.pngCache.get(baseKey);
            if (cached) return cached;
        }

        // Fall back to procedural generation
        return this.fallback.getSprite(name, ...params);
    }

    /**
     * Register a loaded PNG sprite
     */
    registerSprite(name, image) {
        this.pngCache.set(name, image);
    }

    /**
     * Load all PNG sprites from assets/sprites/
     * Returns a promise that resolves when all are loaded (or timeout)
     */
    async loadAll() {
        if (this._loaded) return;

        const manifest = [
            'player', 'npc_sage', 'npc_merchant', 'npc_disciple',
            'tile_grass', 'tile_dirt', 'tile_water', 'tile_path', 'tile_soil', 'tile_fence',
            'crop_seed', 'crop_sprout', 'crop_bud', 'crop_flower', 'crop_fruit',
            'tree', 'rock', 'building_temple', 'building_house',
            'watering_can',
            'interact_talk', 'interact_water', 'interact_plant', 'interact_harvest',
            'meditation_glow', 'emotion_orb', 'heart', 'sparkle'
        ];

        const promises = manifest.map(name => this._tryLoad(name));
        await Promise.allSettled(promises);
        this._loaded = true;
    }

    /**
     * Try loading a single PNG sprite
     */
    _tryLoad(name) {
        return new Promise(resolve => {
            const img = new Image();
            let settled = false;

            const finish = () => {
                if (settled) return;
                settled = true;
                if (img.complete && img.naturalWidth > 0) {
                    this.pngCache.set(name, img);
                }
                resolve();
            };

            img.onload = finish;
            img.onerror = () => {
                // PNG not found — will use procedural fallback, that's fine
                resolve();
            };

            // Support both flat and subdirectory paths
            const path = `assets/sprites/${name}.png`;
            img.src = path;

            // Safety timeout — don't hang loading
            setTimeout(finish, 3000);
        });
    }

    /**
     * Draw a sprite correctly scaled
     */
    drawSprite(ctx, sprite, x, y, width, height) {
        if (!sprite) return;

        if (sprite instanceof HTMLImageElement) {
            // PNG sprite — may be different size than target, scale appropriately
            ctx.drawImage(sprite, x, y, width || sprite.width, height || sprite.height);
        } else if (sprite instanceof HTMLCanvasElement) {
            ctx.drawImage(sprite, x, y, width || sprite.width, height || sprite.height);
        }
    }

    /**
     * Check if a specific sprite is loaded from PNG
     */
    hasPNG(name) {
        const img = this.pngCache.get(name);
        return img instanceof HTMLImageElement && img.complete && img.naturalWidth > 0;
    }

    /**
     * Get the sprite type for rendering decisions
     */
    getSpriteBase(name) {
        if (this.hasPNG(name)) return 'png';
        return 'procedural';
    }
}

/**
 * CanvasScaler — Integer scaling for crisp pixel rendering.
 * 
 * Renders the game at a lower internal resolution and upscales
 * with nearest-neighbor interpolation, giving a classic 16-bit
 * pixel look at any display size.
 * 
 * Usage:
 *   const scaler = new CanvasScaler(displayCanvas, 480, 320);
 *   // Get the internal canvas to render into:
 *   const internalCtx = scaler.getContext();
 *   // After rendering, call this to upscale to display:
 *   scaler.present();
 */

export class CanvasScaler {
    /**
     * @param {HTMLCanvasElement} displayCanvas - The visible canvas element
     * @param {number} internalW - Internal render width (e.g. 480)
     * @param {number} internalH - Internal render height (e.g. 320)
     */
    constructor(displayCanvas, internalW = 480, internalH = 320) {
        this.displayCanvas = displayCanvas;
        this.internalW = internalW;
        this.internalH = internalH;

        // Create internal render canvas
        this.internalCanvas = document.createElement('canvas');
        this.internalCanvas.width = internalW;
        this.internalCanvas.height = internalH;
        this.ctx = this.internalCanvas.getContext('2d');
        this.ctx.imageSmoothingEnabled = false;

        // Track scale factor
        this.scaleX = 1;
        this.scaleY = 1;

        // Set display canvas to internal size initially
        // (will be scaled on first present())
        displayCanvas.width = internalW;
        displayCanvas.height = internalH;

        // Bind resize handler
        this._onResize = this._handleResize.bind(this);
        window.addEventListener('resize', this._onResize);

        // Initial scale
        this._updateScale();
    }

    /**
     * Get the internal rendering context
     */
    getContext() {
        return this.ctx;
    }

    /**
     * Get the internal canvas dimensions
     */
    getInternalSize() {
        return { w: this.internalW, h: this.internalH };
    }

    /**
     * Present the internal buffer to the display canvas
     * Call this after all rendering is done
     */
    present() {
        const dCtx = this.displayCanvas.getContext('2d');
        dCtx.imageSmoothingEnabled = false;
        dCtx.clearRect(0, 0, this.displayCanvas.width, this.displayCanvas.height);

        // Draw internal canvas scaled up to fill display canvas
        dCtx.drawImage(
            this.internalCanvas,
            0, 0, this.internalW, this.internalH,
            0, 0, this.displayCanvas.width, this.displayCanvas.height
        );
    }

    /**
     * Convert screen coordinates to internal game coordinates
     */
    screenToGame(screenX, screenY) {
        return {
            x: (screenX / this.displayCanvas.width) * this.internalW,
            y: (screenY / this.displayCanvas.height) * this.internalH
        };
    }

    /**
     * Convert game coordinates to screen coordinates
     */
    gameToScreen(gameX, gameY) {
        return {
            x: (gameX / this.internalW) * this.displayCanvas.width,
            y: (gameY / this.internalH) * this.displayCanvas.height
        };
    }

    /**
     * Update scale factor based on display size
     */
    _updateScale() {
        const rect = this.displayCanvas.getBoundingClientRect();
        const displayW = Math.floor(rect.width) || 960;
        const displayH = Math.floor(rect.height) || 640;

        // Calculate integer scale factors
        this.scaleX = displayW / this.internalW;
        this.scaleY = displayH / this.internalH;

        // Set display canvas pixel dimensions
        this.displayCanvas.width = displayW;
        this.displayCanvas.height = displayH;
    }

    /**
     * Handle window resize
     */
    _handleResize() {
        this._updateScale();
    }

    /**
     * Clean up
     */
    destroy() {
        window.removeEventListener('resize', this._onResize);
    }
}

